import { round } from "../analysis/round";
import { addDays } from "../date";
import { seededRandom } from "../random";
import { mockWeatherForDate } from "../weather/mock-weather";

/**
 * The demo dataset is generated by formula, never stored by hand, so it is
 * fully reproducible and always labelled SIMULATED DATA.
 */

export const SEED_VERSION = "synthetic-seed-v1";

export const DEMO_START_DATE = "2026-09-01";
export const DEMO_DAY_COUNT = 30;
export const DEMO_COMPANY_NAME = "PT Nusantara Foods (Demo)";
export const DEMO_COMPANY_LOCATION = "Bekasi, Indonesia";

/** Baseline energy intensity the simulated normal days are built around. */
export const DEMO_BASELINE_INTENSITY = 0.53;

/**
 * The primary demo anomaly: production stays flat while electricity jumps.
 * Tuned so the reported deviation lands near the "36% above the selected
 * baseline" figure used in the design copy. Production is unchanged that day.
 */
export const DEMO_ANOMALY_DATE = "2026-09-17";
export const DEMO_ANOMALY_MULTIPLIER = 1.372;

/** A second, milder candidate so the queue is not a single row. */
export const DEMO_SECONDARY_ANOMALY_DATE = "2026-09-24";
export const DEMO_SECONDARY_ANOMALY_MULTIPLIER = 1.231;

export const DEMO_TARIFF_PER_KWH = 1500; // IDR per kWh (tariff, not a bill total)

export interface DemoDay {
  date: string;
  productionUnits: number;
  electricityKwh: number;
  operatingHours: number;
  temperatureC: number;
  humidityPercent: number;
  weather: string;
  electricityPrice: number;
  sourceType: "SIMULATED";
  sourceName: string;
}

export interface DemoDataset {
  company: { name: string; location: string };
  days: DemoDay[];
  tariffPerKwh: number;
  anomalyDate: string;
  secondaryAnomalyDate: string;
  seedVersion: string;
}

/**
 * Production follows a mild, repeating weekly pattern (weekend dip) so the
 * series looks like a real plant without ever being random between runs.
 */
function productionForIndex(index: number): number {
  const base = 1010;
  const weekday = index % 7;
  const weeklyOffset = [0, 8, 14, 6, -6, -22, -34][weekday];
  const slowWave = Math.round(18 * Math.sin(index * 0.7));
  return Math.round(base + weeklyOffset + slowWave);
}

function intensityMultiplierForDate(date: string): number {
  if (date === DEMO_ANOMALY_DATE) return DEMO_ANOMALY_MULTIPLIER;
  if (date === DEMO_SECONDARY_ANOMALY_DATE) return DEMO_SECONDARY_ANOMALY_MULTIPLIER;
  return 1;
}

export function buildDemoDataset(): DemoDataset {
  const random = seededRandom(`opsmind-production:${SEED_VERSION}`);
  const days: DemoDay[] = [];

  for (let index = 0; index < DEMO_DAY_COUNT; index += 1) {
    const date = addDays(DEMO_START_DATE, index);
    const productionUnits = productionForIndex(index);

    // Normal days vary by ±3% around the baseline intensity. Anomaly days raise
    // the intensity while production stays flat.
    const noise = (random() - 0.5) * 0.06;
    const intensity = DEMO_BASELINE_INTENSITY * (1 + noise) * intensityMultiplierForDate(date);
    const electricityKwh = round(productionUnits * intensity, 3);

    const operatingHours = round(10.5 + (random() - 0.5) * 2, 2);
    const weather = mockWeatherForDate(date);

    days.push({
      date,
      productionUnits,
      electricityKwh,
      operatingHours,
      temperatureC: weather.temperatureC,
      humidityPercent: weather.humidityPercent,
      weather: weather.weather,
      electricityPrice: DEMO_TARIFF_PER_KWH,
      sourceType: "SIMULATED",
      sourceName: SEED_VERSION,
    });
  }

  return {
    company: { name: DEMO_COMPANY_NAME, location: DEMO_COMPANY_LOCATION },
    days,
    tariffPerKwh: DEMO_TARIFF_PER_KWH,
    anomalyDate: DEMO_ANOMALY_DATE,
    secondaryAnomalyDate: DEMO_SECONDARY_ANOMALY_DATE,
    seedVersion: SEED_VERSION,
  };
}
